// splitTitles reads known titles off a header line, "Cache read" being two words.
func splitTitles(line string) []string {
	var got []string
	for _, title := range []string{"Agent", "ID", "Model", "In", "Out", "Cache read", "Cache write", "Total", "Share"} {
