}

func TestDotWhileTheParseIsInFlightIsHarmless(t *testing.T) {
	m := withSessions(t, "/p/a.jsonl")
	m, _ = opened(t, m, "right")
	m, _ = opened(t, m, ".")
	m = answer(t, m, sortUsage(1))
