func TestTheBasicFixtureSortsByTotalTokens(t *testing.T) {
	m := withSessions(t, fixtureParent)
	m = feed(t, m, testutil.Resize(120, 20))
	m, cmd := opened(t, m, "enter")
	got := usageMsgs(batchMsgs(t, cmd))
